/* ── scene colours (scene-referred linear, through gl-post's inverse tone curve) ── */
const flat3 = (lin, L) => FACES.reduce((o, _, f) => o.concat(POST.toSceneLinear(lin.map((x) => x * L[f]), 1, PS)), []);
