    A_BOOK = [{ id: 'B', x: tp[0] + pw.a * S1.P / 2, y: tp[1], z: tp[2], text: '+' + P.poolAgents + ' %', sub: 'ONE NUMBER FOR ALL FIVE FIFTHS', role: 'result', size: KN.poolPinSize, priority: 1 }];
